"""Offline request/clock regression; synthetic manifest is never release authority."""
import copy
import hashlib
import importlib.util
import json
from pathlib import Path
import subprocess
import sys
import tempfile
import time
import unittest

HERE = Path(__file__).resolve().parent

def load(name):
    spec = importlib.util.spec_from_file_location(name, HERE / (name + ".py"))
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module

binding = load("diagnostic-restoration")
collector = load("disclosure-diagnostic")


FIREWALL_BEFORE = b"""# Generated by iptables-save v1.8.10 (nf_tables) on Wed Nov 18 14:10:02 2026
*filter
:INPUT ACCEPT [5051269:2916377518]
:OUTPUT ACCEPT [0:0]
[3:180] -A INPUT -p tcp --dport 22 -m comment --comment "keep [7:8]" -j ACCEPT
[4:240] -A INPUT -p tcp --dport 443 -j DROP
COMMIT
*nat
:OUTPUT ACCEPT [5226:326684]
COMMIT
# Completed on Wed Nov 18 14:10:02 2026
"""
FIREWALL_LATER = (FIREWALL_BEFORE.replace(b"14:10:02", b"15:07:46")
                  .replace(b"[5051269:2916377518]", b"[5051270:2916377578]")
                  .replace(b"[5226:326684]", b"[5227:326744]")
                  .replace(b"[3:180]", b"[5:300]"))


class DiagnosticFirewallFingerprint(unittest.TestCase):
    def test_readbacks_with_new_counters_match(self):
        self.assertEqual(binding.firewall_fingerprint(FIREWALL_BEFORE),
                         binding.firewall_fingerprint(FIREWALL_LATER))

    def test_multiline_rule_comment_is_preserved(self):
        comment = (b'keep \\"[7:8]\\" and \\\\'
                   b"\n:INPUT ACCEPT [9:10]\n[11:12] -A INPUT\n# Completed on literal")
        baseline = FIREWALL_BEFORE.replace(b"keep [7:8]", comment)
        for old, new in ((b"[9:10]", b"[13:14]"), (b"[11:12]", b"[15:16]"),
                         (b"Completed on literal", b"Completed on changed"),
                         (b"\n:INPUT", b"\r:INPUT")):
            with self.subTest(token=old):
                changed = FIREWALL_BEFORE.replace(b"keep [7:8]", comment.replace(old, new))
                self.assertNotEqual(binding.firewall_fingerprint(changed),
                                    binding.firewall_fingerprint(baseline))

    def test_rule_and_policy_changes_are_detected(self):
        lines = FIREWALL_LATER.splitlines(keepends=True)
        reordered = b"".join(lines[:4] + [lines[5], lines[4]] + lines[6:])
        baseline = binding.firewall_fingerprint(FIREWALL_BEFORE)
        changed = {
            "policy": FIREWALL_LATER.replace(b":INPUT ACCEPT", b":INPUT DROP"),
            "port": FIREWALL_LATER.replace(b"--dport 443", b"--dport 8443"),
            "target": FIREWALL_LATER.replace(b"-j DROP", b"-j ACCEPT"),
            "comment": FIREWALL_LATER.replace(b"keep [7:8]", b"keep [9:10]"),
            "rule order": reordered,
            "table": FIREWALL_LATER.replace(b"*nat", b"*mangle"),
        }
        for change, snapshot in changed.items():
            with self.subTest(change=change):
                self.assertNotEqual(binding.firewall_fingerprint(snapshot), baseline)


class DiagnosticRestoration(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.now = int(time.time())
        self.window = dict(start_unix=self.now-10, test_until_unix=self.now-10+7200, finish_unix=self.now-10+10800)
        self.prepare_request()

    def prepare_request(self, mode=None):
        manifest = {"schema":"sbxr-qualification-manifest-v3", "v3_attempt":{
            "diagnostic":self.window, "scenario_limit_seconds":1800, "required_scenarios":["mvp-install"], "attempt_id":"run-999001-attempt-1"}}
        if mode is not None:
            self.window["mode"] = mode
            manifest["v3_attempt"]["scenario_limit_seconds"] = 2700
            manifest["v3_attempt"]["attempt_id"] = "run-999002-attempt-1"
        self.raw = collector.canonical(manifest)
        self.digest = hashlib.sha256(self.raw).hexdigest()
        self.manifest = self.root / "manifest.json"
        self.manifest.write_bytes(self.raw)
        self.manifest.chmod(0o600)
        clock = (HERE / "mvp-observe.py").read_bytes()
        stage = dict(clock=clock, clock_sha256=collector.digest(clock)) if mode else {}
        if mode:
            collector.write_bytes_new(self.manifest.with_name("runtime-deadline"),
                                      f"{self.now+2700}\n".encode())
        handoff = collector.prepare(self.root, self.manifest, self.now, **stage)
        self.directory = Path(handoff["directory"])
        self.q = json.loads((self.directory / "request.json").read_bytes())
        self.request_path = f"/root/{self.directory.name}/request.json"
        self.draft_path = f"/root/{self.directory.name}/observation-draft.json"

    def validate(self, q=None, raw=None, digest=None, request=None, draft=None, window=None):
        return binding.validate_request(self.q if q is None else q, self.raw if raw is None else raw,
            self.digest if digest is None else digest, self.request_path if request is None else request,
            self.draft_path if draft is None else draft, self.window if window is None else window)

    def clock(self, command):
        recorder = self.directory if self.window.get("mode") == "karing-one-node" else HERE
        return subprocess.run([sys.executable, "-B", str(recorder / "mvp-observe.py"), command,
            "--request", str(self.directory / "request.json"), "--draft", str(self.directory / "observation-draft.json")],
            capture_output=True, timeout=10)

    def test_one_node_clock_through_collector_validator_and_recorder(self):
        self.prepare_request("karing-one-node")
        self.assertEqual(self.validate(), self.window)
        self.assertEqual(self.q["required_checks"], ["diagnostic-karing-one-node"])
        self.assertEqual(self.q["scenario_limit_seconds"], 2700)
        self.assertEqual(self.q["deadline_unix"], self.now + 2700)
        self.assertEqual(self.q["diagnostic_test_until_unix"], self.now + 1200)
        self.assertNotIn("attended_finish_by", self.q)
        self.assertNotIn("karing_response_limit_seconds", self.q)
        self.assertEqual(binding.operation_cutoff(self.q, self.now+2000, self.now+2400), self.now+500)
        self.assertEqual(binding.operation_cutoff(self.q, self.now+2400, self.now+1900), self.now+400)
        request = self.directory / "request.json"
        draft = self.directory / "observation-draft.json"
        self.assertEqual(self.clock("start").returncode, 0)
        self.assertEqual(int(self.clock("operation-deadline").stdout), self.now+1200)
        self.assertEqual(int(self.clock("cleanup-deadline").stdout), self.now+2700)
        draft.unlink()  # Probe request admission independently of the previous draft digest.
        for edit in (dict(required_checks=["diagnostic-observation"]), dict(scenario_limit_seconds=1800),
                     dict(diagnostic_test_until_unix=self.now+1201), dict(scenario_id="mvp-subscription")):
            altered = dict(self.q, **edit)
            with self.subTest(edit=edit):
                with self.assertRaises(ValueError):
                    self.validate(q=altered)
                request.write_bytes(collector.canonical(altered))
                self.assertNotEqual(self.clock("deadline").returncode, 0)
        ordinary = dict(self.q)
        del ordinary["diagnostic_test_until_unix"]
        ordinary["required_checks"] = ["packaged-install"]
        request.write_bytes(collector.canonical(ordinary))
        self.assertNotEqual(self.clock("deadline").returncode, 0)

    def test_real_collector_request_needs_no_attendance_claim(self):
        self.assertNotIn("attended_finish_by", self.q)
        self.assertEqual(self.validate(), self.window)
        with self.assertRaises(KeyError):
            _ = self.q["attended_finish_by"]  # Previous caller failed here.

    def test_real_recorder_keeps_removal_reserve(self):
        request = self.directory / "request.json"
        draft = self.directory / "observation-draft.json"
        result = self.clock("start")
        self.assertEqual(result.returncode, 0, result.stderr)
        before = (request.read_bytes(), draft.read_bytes())
        ordinary, cleanup = self.clock("operation-deadline"), self.clock("cleanup-deadline")
        self.assertEqual((ordinary.returncode, cleanup.returncode), (0, 0))
        self.assertGreaterEqual(int(cleanup.stdout)-int(ordinary.stdout), 900)
        self.assertEqual(int(cleanup.stdout), self.q["deadline_unix"])
        self.assertEqual(before, (request.read_bytes(), draft.read_bytes()))

    def test_operation_cutoff_reserves_restoration_once(self):
        cutoff = binding.operation_cutoff(self.q, self.window["finish_unix"], self.window["finish_unix"])
        self.assertEqual(cutoff, self.q["diagnostic_test_until_unix"])
        self.assertEqual(self.q["deadline_unix"]-cutoff, 900)
        self.assertLess(self.now+90+10, cutoff)
        self.assertGreaterEqual(self.now+90+10+900, cutoff)  # Old duplicate subtraction refused.

    def test_earlier_runtime_and_approval_keep_full_reserve(self):
        for runtime, finish in ((self.now+1500,self.window["finish_unix"]),
                                (self.window["finish_unix"],self.now+1400),
                                (self.now+800,self.window["finish_unix"])):
            with self.subTest(runtime=runtime, finish=finish):
                cutoff=binding.operation_cutoff(self.q,runtime,finish)
                cleanup=min(self.q["deadline_unix"],runtime,finish)
                self.assertGreaterEqual(cleanup-cutoff,900)
                self.assertLessEqual(cutoff,self.q["diagnostic_test_until_unix"])
        self.assertLess(binding.operation_cutoff(self.q,self.now+800,self.window["finish_unix"]),self.now)

    def test_cutoff_refuses_noninteger_and_nondiagnostic_input(self):
        for runtime,finish in ((True,self.window["finish_unix"]),(float("inf"),self.window["finish_unix"]),
                               (self.window["finish_unix"],0)):
            with self.subTest(runtime=runtime,finish=finish), self.assertRaises(ValueError):
                binding.operation_cutoff(self.q,runtime,finish)
        q=copy.deepcopy(self.q);q.pop("diagnostic_test_until_unix")
        with self.assertRaises(ValueError):binding.operation_cutoff(q,self.window["finish_unix"],self.window["finish_unix"])

    def test_nonobject_window_is_refused(self):
        with self.assertRaises(ValueError):
            self.validate(window=[])

    def test_refuses_wrong_paths_digest_and_window(self):
        for change in ({"request":"/root/sbxr-qualification-evidence/request.json"},
                       {"draft":"/root/mvp-observation-draft.json"}, {"digest":"0"*64},
                       {"window":dict(self.window, finish_unix=self.window["finish_unix"]+1)}):
            with self.subTest(change=change), self.assertRaises(ValueError): self.validate(**change)

    def test_refuses_scope_or_reserve_changes(self):
        for key,value in (("attended_finish_by","2099-01-01T00:00:00Z"), ("deadline_unix",self.q["deadline_unix"]+1),
                          ("diagnostic_test_until_unix",self.q["diagnostic_test_until_unix"]+1),
                          ("required_checks",["packaged-install"]), ("scenario_id","mvp-removal"),
                          ("scenario_limit_seconds",True), ("qualification_manifest_sha256","f"*64)):
            q=copy.deepcopy(self.q);q[key]=value
            with self.subTest(key=key), self.assertRaises(ValueError): self.validate(q=q)

    def test_refuses_nondiagnostic_or_attended_manifest(self):
        for key,value in (("required_scenarios",["mvp-install","mvp-removal"]),
                          ("attended_finish_by","2099-01-01T00:00:00Z"), ("karing_response_limit_seconds",3600),
                          ("proxy_profile","vless-vmess"), ("owner_exception","override")):
            m=json.loads(self.raw);m["v3_attempt"][key]=value;raw=collector.canonical(m)
            with self.subTest(key=key), self.assertRaises(ValueError):
                self.validate(raw=raw,digest=hashlib.sha256(raw).hexdigest())

if __name__ == "__main__": unittest.main()
